function renderCalibration(){const steering=findDeep(configData('vehicle'),'steering_calibration_valid'),circle=findDeep(configData('vehicle'),'steering_circle_calibration_valid'),drive=findDeep(configData('vehicle'),'drive_odometry_calibration_valid'),imuValid=findDeep(configData('imu'),'stationary_calibration_valid'),cameraMetric=findDeep(configData('perception'),'camera_metric_calibration_validated');setText('calSteeringFlag',passText(steering));setText('calCircleFlag',passText(circle));setText('calDriveFlag',passText(drive));setText('calImuFlag',passText(imuValid));const loc=obj('localization_state'),planning=bool(raw('system.planning_localization_ready')),motion=bool(raw('system.motion_localization_ready')),fusion=bool(raw('gnss_velocity_fusion_active'))&&bool(raw('gnss_cog_fusion_active'));setChip('calGnssChip',planning,planning?'PLANNING READY':'WAIT',planning?'PLANNING READY':'WAIT');setText('calLocMode',getPath(loc,'mode','state','raw')||'--');setText('calPlanningReady',planning?'READY':'WAIT');setText('calMotionReady',motion?'READY':'LOCKED');setText('calGnssFusion',fusion?'ACTIVE':'WAIT');const steerReady=bool(raw('esc_calibration_controller_ready'));setChip('calSteerChip',steering===true&&steerReady,'CALIBRATED','WAIT');setText('calSteerController',steerReady?'READY':'WAIT');setText('calSteerTarget',fmt(deg(raw('esc_steer_target')),2)+'°');setText('calSteerActual',fmt(deg(raw('esc_steer_actual')),2)+'°');setText('calSteerProtocol',fmt(deg(raw('esc_steer_feedback_raw')),2)+'°');const cam=bool(raw('connected.camera')),healthy=bool(raw('camera_healthy')),fresh=channelFresh('camera_health_state',3);setChip('calCameraChip',cameraMetric===true&&healthy,'VALIDATED','WAIT');setText('calCameraUsb',cam?'CONNECTED':'OFFLINE');setText('calCameraHealth',healthy?'HEALTHY':'WAIT');setText('calCameraMetric',passText(cameraMetric));setText('calPerceptionFresh',fresh?'FRESH':'STALE / WAIT');const im=obj('imu');setChip('calImuChip',imuValid===true&&bool(raw('connected.imu')),'VALIDATED','WAIT');setText('calImuUsb',bool(raw('connected.imu'))?'CONNECTED':'OFFLINE');setText('calImuStationary',passText(imuValid));setText('calImuYaw',fmt(deg(im.yaw_rad),2)+'°');setText('calImuGz',fmt(im.gz,4)+' rad/s')}
function drawTuneSpark(){const c=$('tuneSpark');if(!c)return;const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);const css=getComputedStyle(document.body);ctx.strokeStyle=css.getPropertyValue('--border2');ctx.beginPath();ctx.moveTo(0,h/2);ctx.lineTo(w,h/2);ctx.stroke();if(history.length<2)return;const max=Math.max(.2,...history.flatMap(x=>[Math.abs(x.final),Math.abs(x.actual)]));[['final','--green'],['actual','--cyan']].forEach(([key,col])=>{ctx.strokeStyle=css.getPropertyValue(col);ctx.lineWidth=2;ctx.beginPath();history.forEach((p,i)=>{const x=i/(history.length-1)*w,y=h/2-(p[key]/max)*(h*.40);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()})}
function renderTuning(){setText('tuneMppiReady',bool(raw('mppi_closed_loop_ready'))?'READY':'WAIT');setText('tuneSmoother',bool(raw('smoother_closed_loop_eligible'))?'ELIGIBLE':'WAIT');setText('tuneVelErr',fmt(raw('mppi_velocity_error'),3)+' m/s');setText('tuneSteerErr',fmt(deg(raw('mppi_steering_error')),2)+'°');setText('tuneNavCmd',fmt(obj('cmd_nav').linear_x,3)+' m/s');setText('tuneFinalCmd',fmt(obj('cmd_final').linear_x,3)+' m/s');setText('tuneDriveTarget',fmt(raw('esc_drive_target'),3)+' m/s');setText('tuneDriveActual',fmt(raw('esc_drive_actual'),3)+' m/s');setText('tuneSteerTarget',fmt(deg(raw('esc_steer_target')),2)+'°');setText('tuneSteerActual',fmt(deg(raw('esc_steer_actual')),2)+'°');setText('tuneQualification',pretty({mppi:obj('mppi_status'),smoother:obj('smoother_qualification'),velocity_error_mps:raw('mppi_velocity_error'),steering_error_rad:raw('mppi_steering_error'),yaw_rate_error_rps:raw('mppi_yaw_error')}));setText('tuneNavConfig',pretty(configData('nav2')));setText('tuneVehicleConfig',pretty({vehicle:configData('vehicle'),esc:configData('esc'),teleop:configData('teleop')}));drawTuneSpark()}
function currentWarnings(){let n=0;if(bool(raw('system.estop')))n++;if(!bool(raw('connected.esc_feedback')))n++;if(!bool(raw('connected.gnss')))n++;if(!bool(raw('connected.imu')))n++;if(!bool(raw('system.motion_ready')))n++;return n}
function renderReports(){const keys=Object.keys(state),fresh=keys.filter(k=>age(k)<3).length;setText('reportChannels',keys.length);setText('reportFresh',fresh);setText('reportWarnings',currentWarnings());setText('reportTimestamp','Snapshot '+new Date().toLocaleString('id-ID'));setText('reportSnapshot',pretty({goal:obj('goal_state'),pose:obj('ekf_global'),gnss:obj('gnss_quality'),imu:obj('imu'),esc:{status:obj('esc_status'),target:raw('esc_drive_target'),actual:raw('esc_drive_actual')},perception:obj('perception_performance'),safety:{motion_ready:raw('system.motion_ready'),estop:raw('system.estop')}}))}
function downloadBlob(name,type,text){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadLatestRecordingCsv(name='',url='/api/experiment/record/last.csv'){const target=url||'/api/experiment/record/last.csv';window.location.assign(target);return name||'CSV hasil run'}
function stamp(){return new Date().toISOString().replace(/[:.]/g,'-')}
function csvCell(v){const s=typeof v==='string'?v:JSON.stringify(v);return '"'+String(s??'').replace(/"/g,'""')+'"'}
function exportSummaryCsv(){const rows=[['channel','value','age_s'],...Object.keys(state).sort().map(k=>[k,textish(state[k]),Number.isFinite(age(k))?age(k).toFixed(3):''])];downloadBlob('adv_runtime_'+stamp()+'.csv','text/csv;charset=utf-8',rows.map(r=>r.map(csvCell).join(',')).join('\n'))}
