function effectiveExperimentList(){let list=[...(experiments[currentExp]||[])];if(currentExp==='navigation'&&list.some(x=>/^N\d+\.\d+$/.test(String(x.id||''))))list=list.filter(x=>/^N(?:[1-9]\d*)\.\d+$/.test(String(x.id||'')));if(currentExp==='perception')list=list.filter(x=>!String(x.id||'').startsWith('F'));return list.sort(compareExperiment)}
function displayExperimentId(x){const id=String(x?.id||'');let m;if((m=id.match(/^N(\d+)\.(\d+)$/)))return `${+m[1]}.${+m[2]}`;if((m=id.match(/^4\.(\d+)\.(\d+)$/)))return `${+m[1]}.${+m[2]}`;if((m=id.match(/^4\.(\d+)$/)))return `${+m[1]}.1`;if((m=id.match(/^F4\.(\d+)$/)))return `Final ${+m[1]}.1`;return id.replace(/^N(?=\d)/,'')}
function reportRunId(x=selectedExperiment,domain=currentExp){const id=String(x?.id||'').trim();if(domain==='navigation')return /^N\d+\.\d+$/.test(id)?id:`N${displayExperimentId(x)}`;let d=displayExperimentId(x).replace(/^Final\s+/i,'').replace(/[^0-9.]/g,'');if(!d)d='0.0';return (domain==='perception'?'P':'E')+d}
