function tuningFieldsFor(x){const catalog=(x.parameterFields||[]).filter(p=>p.yamlFileKey||p.isGroundTruth),extra=[];if(currentExp==='steering'&&x?.id==='4.1'){extra.push({label:'STM protocol full scale (deg)',yamlFileKey:'esc',yamlPath:'esc_ackermann.ros__parameters.serial_left_max_deg',kind:'float',group:'Steering Command Domain',help:'Range command STM, -90° sampai +90°.'});extra.push({label:'HMI command full scale (deg)',yamlFileKey:'hmi',yamlPath:'stmf4_hmi_bridge.ros__parameters.hmi_steer_full_scale_deg',kind:'float',group:'Steering Command Domain',help:'Full-scale tombol LEFT/RIGHT Web dan TFT.'})}const base=catalog.some(p=>p.yamlFileKey)?catalog:(WEB_TUNING[currentExp]?.[x.id]||[]),seen=new Set(),out=[];for(const p of [...extra,...base]){const k=`${p.yamlFileKey||''}:${p.yamlPath||p.key||p.label}`;if(seen.has(k))continue;seen.add(k);out.push(p)}return out}
function configValue(file,path){let n=configs[file]?.data;if(n==null)return undefined;for(const part of String(path||'').split('.').filter(Boolean)){if(Array.isArray(n)&&/^\d+$/.test(part))n=n[+part];else if(n&&typeof n==='object')n=n[part];else return undefined}return n}
