async function loadExperiments(){try{experiments=await (await fetch('/api/experiments',{cache:'no-store'})).json();setText('labLeafCount',Object.values(experiments).reduce((n,a)=>n+(a?.length||0),0));setText('navTestCount',(experiments.navigation||[]).length);setText('perTestCount',(experiments.perception||[]).length);setText('escTestCount',(experiments.steering||[]).length);renderExperimentList();const list=effectiveExperimentList();if(list.length)selectExperimentById(list[0].id)}catch(e){$('experimentList').innerHTML='<div class="empty-state">Catalog unavailable: '+escapeHtml(e.message)+'</div>'}}
function renderExperimentList(){const all=effectiveExperimentList();setText('labLeafCount',all.length);const box=$('experimentList');if(!box)return;const term=($('experimentSearch')?.value||'').trim().toLowerCase();const list=all.filter(x=>!term||`${displayExperimentId(x)} ${displayExperimentTitle(x)} ${displayExperimentGroup(x)} ${x.id}`.toLowerCase().includes(term));const visited=visitedSet();let lastGroup='',html='';for(const x of list){const group=displayExperimentGroup(x),displayId=displayExperimentId(x),title=displayExperimentTitle(x);if(group!==lastGroup){html+=`<div class="chapter-group"><span>${escapeHtml(group)}</span></div>`;lastGroup=group}html+=`<button class="experiment-item ${selectedExperiment?.id===x.id?'active':''}" data-id="${escapeHtml(x.id)}"><i>${visited.has(x.id)?'✓':'○'}</i><div><span>${escapeHtml(displayId)}</span><b>${escapeHtml(title)}</b><small>${(x.tableNames||[]).length} tabel • ${(x.graphCaptions||[]).length} grafik • ${tuningFieldsFor(x).filter(p=>p.yamlFileKey).length} parameter</small></div></button>`}box.innerHTML=html||'<div class="empty-state">Tidak ada tahap tuning yang cocok.</div>';qa('.experiment-item',box).forEach(e=>e.onclick=()=>selectExperimentById(e.dataset.id));setText('chapterDomainTitle',currentExp==='navigation'?'Navigasi':currentExp==='perception'?'Persepsi':'ESC / FOC');renderChapterProgress();if(activeDomain!=='overview')renderContextNav()}
